from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def parse(tokens: list[Token]) -> Statement:
    """Parse exactly one statement, optionally followed by a single ';',
    then EOF.

    Raises:
        SQLSyntaxError: if the tokens are not exactly one valid statement
            (including empty input, a lone ';', or trailing tokens).
    """
    if not tokens:
        raise SQLSyntaxError("Expected statement")

    token = tokens.pop(0)
    if token.type != TokenType.KEYWORD:
        raise SQLSyntaxError(f"Unexpected token: {token.value}")

    if token.value == "CREATE":
        return _parse_create_table(tokens)
    elif token.value == "DROP":
        return _parse_drop_table(tokens)
    elif token.value == "INSERT":
        return _parse_insert(tokens)
    elif token.value == "SELECT":
        return _parse_select(tokens)
    elif token.value == "DELETE":
        return _parse_delete(tokens)
    else:
        raise SQLSyntaxError(f"Unknown statement: {token.value}")

    if tokens and tokens[0].value == ";":
        tokens.pop(0)

    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after statement")

    return stmt
def _parse_create_table(tokens: list[Token]) -> CreateTableStmt:
    if not tokens or tokens.pop(0).value != "TABLE":
        raise SQLSyntaxError("Expected TABLE")

    table_token = tokens.pop(0)
    if table_token.type != TokenType.IDENTIFIER:
        raise SQLSyntaxError(f"Expected table name, got {table_token.value}")

    if not tokens or tokens.pop(0).value != "(":
        raise SQLSyntaxError("Expected (")

    columns = []
    while tokens:
        token = tokens.pop(0)
        if token.type == TokenType.EOF:
            raise SQLSyntaxError("Expected )")
        elif token.type != TokenType.IDENTIFIER:
            raise SQLSyntaxError(f"Expected column name, got {token.value}")

        col_name = token.value

        type_token = tokens.pop(0)
        if type_token.type != TokenType.KEYWORD or type_token.value not in ("INTEGER", "TEXT", "BOOLEAN"):
            raise SQLSyntaxError(f"Expected column type, got {type_token.value}")

        col_type = ColumnType[type_token.value]

        columns.append(ColumnDef(col_name, col_type))

        next_token = tokens.pop(0)
        if next_token.value == ")":
            break
        elif next_token.value != ",":
            raise SQLSyntaxError(f"Expected , or ), got {next_token.value}")

    if not tokens or tokens.pop(0).type != TokenType.EOF:
        raise SQLSyntaxError("Expected EOF")

    return CreateTableStmt(table_token.value, tuple(columns))
def _parse_drop_table(tokens: list[Token]) -> DropTableStmt:
    if not tokens or tokens.pop(0).value != "TABLE":
        raise SQLSyntaxError("Expected TABLE")

    table_token = tokens.pop(0)
    if table_token.type != TokenType.IDENTIFIER:
        raise SQLSyntaxError(f"Expected table name, got {table_token.value}")

    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after DROP TABLE")

    return DropTableStmt(table_token.value)
