    if not tokens or tokens.pop(0).value != "INTO":
        raise SQLSyntaxError("Expected INTO")

    table_token = tokens.pop(0)
    if table_token.type != TokenType.IDENTIFIER:
        raise SQLSyntaxError(f"Expected table name, got {table_token.value}")

    columns = None
    if tokens and tokens[0].value == "(":
        tokens.pop(0)
        columns = []
        while tokens:
            token = tokens.pop(0)
            if token.type == TokenType.EOF:
                raise SQLSyntaxError("Expected )")
            elif token.type != TokenType.IDENTIFIER:
                raise SQLSyntaxError(f"Expected column name, got {token.value}")

            columns.append(token.value)

            next_token = tokens.pop(0)
            if next_token.value == ")":
                break
            elif next_token.value != ",":
                raise SQLSyntaxError(f"Expected , or ), got {next_token.value}")

    if not tokens or tokens.pop(0).value != "VALUES":
        raise SQLSyntaxError("Expected VALUES")

    if not tokens or tokens.pop(0).value != "(":
        raise SQLSyntaxError("Expected (")

    values = []
    while tokens:
        token = tokens.pop(0)
        if token.type == TokenType.EOF:
            raise SQLSyntaxError("Expected )")
        elif token.type == TokenType.INTEGER:
            values.append(int(token.value))
        elif token.type == TokenType.STRING:
            values.append(token.value)
        elif token.type == TokenType.KEYWORD and token.value == "TRUE":
            values.append(True)
        elif token.type == TokenType.KEYWORD and token.value == "FALSE":
            values.append(False)
        elif token.type == TokenType.KEYWORD and token.value == "NULL":
            values.append(None)
        else:
            raise SQLSyntaxError(f"Expected literal value, got {token.value}")

        next_token = tokens.pop(0)
        if next_token.value == ")":
            break
        elif next_token.value != ",":
            raise SQLSyntaxError(f"Expected , or ), got {next_token.value}")

    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after INSERT")

    return InsertStmt(table_token.value, tuple(columns) if columns else None, tuple(values))
def _parse_select(tokens: list[Token]) -> SelectStmt:
    if not tokens or tokens[0].value != "*":
        columns = []
