                raise SQLSyntaxError(f"Expected column name, got {token.value}")

            columns.append(token.value)

            next_token = tokens.pop(0)
            if next_token.value == "FROM":
                break
            elif next_token.value != ",":
                raise SQLSyntaxError(f"Expected , or FROM, got {next_token.value}")
    else:
        columns = None
        tokens.pop(0)

    if not tokens or tokens.pop(0).value != "FROM":
        raise SQLSyntaxError("Expected FROM")

    table_token = tokens.pop(0)
    if table_token.type != TokenType.IDENTIFIER:
        raise SQLSyntaxError(f"Expected table name, got {table_token.value}")

    where = None
    if tokens and tokens[0].value == "WHERE":
        tokens.pop(0)
        where = parse_expression(tokens)

    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after SELECT")

    return SelectStmt(table_token.value, tuple(columns) if columns else None, where)
def _parse_delete(tokens: list[Token]) -> DeleteStmt:
    if not tokens or tokens.pop(0).value != "FROM":
        raise SQLSyntaxError("Expected FROM")

    table_token = tokens.pop(0)
    if table_token.type != TokenType.IDENTIFIER:
        raise SQLSyntaxError(f"Expected table name, got {table_token.value}")

    where = None
