    """
    expr = _parse_or_expr(tokens)

    if tokens and tokens[0].type != TokenType.EOF:
        raise SQLSyntaxError("Trailing tokens after expression")

    return expr
def _parse_or_expr(tokens: list[Token]) -> Expr:
    expr = _parse_and_expr(tokens)

    while tokens and tokens[0].value == "OR":
        tokens.pop(0)
        right = _parse_and_expr(tokens)
        expr = Or(expr, right)

    return expr
def _parse_and_expr(tokens: list[Token]) -> Expr:
    expr = _parse_not_expr(tokens)

    while tokens and tokens[0].value == "AND":
        tokens.pop(0)
        right = _parse_not_expr(tokens)
        expr = And(expr, right)

    return expr
def _parse_not_expr(tokens: list[Token]) -> Expr:
    if tokens and tokens[0].value == "NOT":
        tokens.pop(0)
        operand = _parse_predicate(tokens)
        return Not(operand)

    return _parse_predicate(tokens)
def _parse_predicate(tokens: list[Token]) -> Expr:
    left = _parse_primary(tokens)

    if tokens and tokens[0].value in COMPARISON_OPS:
        op = tokens.pop(0).value
        right = _parse_primary(tokens)
        return Comparison(op, left, right)

    if tokens and tokens[0].value == "IS":
        tokens.pop(0)
        if tokens and tokens[0].value == "NOT":
            tokens.pop(0)
            if tokens and tokens[0].value == "NULL":
                tokens.pop(0)
                return IsNull(left, True)
        elif tokens and tokens[0].value == "NULL":
            tokens.pop(0)
            return IsNull(left, False)

    raise SQLSyntaxError(f"Unexpected token: {tokens[0].value}")
def _parse_primary(tokens: list[Token]) -> Expr:
    if not tokens:
        raise SQLSyntaxError("Expected primary expression")

    token = tokens.pop(0)
    if token.type == TokenType.INTEGER:
        return Literal(int(token.value))
    elif token.type == TokenType.STRING:
        return Literal(token.value)
    elif token.type == TokenType.KEYWORD and token.value == "TRUE":
        return Literal(True)
    elif token.type == TokenType.KEYWORD and token.value == "FALSE":
        return Literal(False)
    elif token.type == TokenType.KEYWORD and token.value == "NULL":
        return Literal(None)
    elif token.type == TokenType.IDENTIFIER:
        return ColumnRef(token.value)
    elif token.type == TokenType.OPERATOR and token.value == "(":
        expr = parse_expression(tokens)
        if not tokens or tokens[0].value != ")":
            raise SQLSyntaxError("Expected )")
        tokens.pop(0)
        return expr
    else:
        raise SQLSyntaxError(f"Unexpected token: {token.value}")

